create table if not exists public.careerlab_profiles(user_id uuid primary key,email text not null,display_name text not null default 'CareerLab user',plan text not null default 'free' check(plan in ('free','pro')),is_admin boolean not null default false,plan_started_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.careerlab_settings(id integer primary key,plans_enabled boolean not null default false,features jsonb not null default '{"project":true,"skill_gap":true,"interview_feedback":true,"job_finder":true}'::jsonb,pro_price_paise integer not null default 49900,updated_at timestamptz not null default now());
insert into public.careerlab_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.careerlab_payments(id bigint generated by default as identity primary key,user_id uuid not null,email text,razorpay_order_id text unique not null,razorpay_payment_id text,razorpay_signature text,amount integer not null,currency text not null default 'INR',plan text not null default 'pro',status text not null default 'created',created_at timestamptz not null default now(),verified_at timestamptz);
alter table public.careerlab_profiles enable row level security;alter table public.careerlab_settings enable row level security;alter table public.careerlab_payments enable row level security;revoke all on public.careerlab_profiles from anon,authenticated;revoke all on public.careerlab_settings from anon,authenticated;revoke all on public.careerlab_payments from anon,authenticated;grant all on public.careerlab_profiles to service_role;grant all on public.careerlab_settings to service_role;grant all on public.careerlab_payments to service_role;grant usage,select on sequence public.careerlab_payments_id_seq to service_role;
